  let z = cam.z;
  let focal = frame.splatParams.zw;
  let viewport = max(frame.splatParams.xy, vec2<f32>(1.0, 1.0));
  let j = mat3x3<f32>(
    vec3<f32>(focal.x / z, 0.0, -(focal.x * cam.x) / (z * z)),
    vec3<f32>(0.0, focal.y / z, -(focal.y * cam.y) / (z * z)),
    vec3<f32>(0.0, 0.0, 0.0)
  );
